    //                            MODE BIT PATTERN (UNSPECIFIED=0,
    //                            EXACTLY=0x40000000, AT_MOST=0x80000000),
    //                            NOT a 0/1/2 index. T279 (2026-11-28): the
    //                            previous (spec >> 30) & 3 returned the
    //                            index; androidx compose
